285	    public Pet getPet(String name, boolean ignoreNew) {
286	        name = name.toLowerCase();
287	        for (Pet pet : getPetsInternal()) {
288	            if (!ignoreNew || !pet.isNew()) {
289	                String compName = pet.getName();
290	                compName = compName.toLowerCase();
291	                if (compName.equals(name)) {
292	                    return pet;
293	                }
294	            }
295	        }
296	        return null;
