1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
12	 * through. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or
13	 * empty)}: a full-key match with an existing owner is a duplicate (409); any differing component (a
14	 * different telephone, email, or household) is a distinct identity that is allowed.
15	 *
16	 * <p>Not an OfficeFloor function class — a plain helper shared by the create-owner steps so the key
17	 * derived at the uniqueness check, the household id assigned to the entity, and the key returned in
18	 * the response are all computed the same way.
19	 */
20	public final class OwnerIdentity {
21	
22	    private OwnerIdentity() {
23	    }
24	
25	    /**
26	     * Assembles the identity key from its three components. {@code telephone} is expected in E.164
27	     * form and {@code email} already normalized (trimmed, lower-cased); a null/blank email or a null
28	     * householdId contributes an empty component.
29	     */
30	    public static String key(String telephone, String email, String householdId) {
31	        String tel = telephone == null ? "" : telephone;
32	        String mail = (email == null || email.isBlank()) ? "" : email;
33	        String hh = householdId == null ? "" : householdId;
34	        return tel + "|" + mail + "|" + hh;
35	    }
36	
37	    /** Best-effort E.164 for a stored telephone; falls back to the raw value when it cannot form E.164. */
38	    public static String toE164(String telephone) {
39	        try {
40	            return TelephoneE164.toE164(telephone);
41	        }
42	        catch (InvalidTelephoneException ex) {
43	            return telephone;
44	        }
45	    }
46	
47	    /** Trimmed, lower-cased email, or null when absent — matching {@link NormalizeOwnerEmail}. */
48	    public static String normalizeEmail(String email) {
49	        if (email == null || email.isBlank()) {
50	            return null;
51	        }
52	        return email.trim().toLowerCase(Locale.ROOT);
53	    }
54	
55	    /**
56	     * Stable, shared household id: the first 12 upper-hex chars of SHA-256 over the canonical last
57	     * name and the postcode ({@code normalizedLastName + '|' + postcode}), so every owner with the
58	     * same last name and postcode derives the same value automatically — the household is keyed on
59	     * (lastName, postcode) alone. A null postcode contributes an empty component.
60	     */
61	    public static String householdId(String lastName, String postcode) {
62	        String normalizedLastName = canonicalName(lastName);
63	        String pc = postcode == null ? "" : postcode;
64	        try {
65	            byte[] hash = MessageDigest.getInstance("SHA-256")
66	                    .digest((normalizedLastName + "|" + pc).getBytes(StandardCharsets.UTF_8));
67	            StringBuilder sb = new StringBuilder(12);
68	            for (int i = 0; i < 6; i++) {
69	                sb.append(String.format("%02X", hash[i]));
70	            }
71	            return sb.toString();
72	        }
73	        catch (NoSuchAlgorithmException ex) {
74	            throw new IllegalStateException("SHA-256 not available", ex);
75	        }
76	    }
77	
78	    /** Lower-cased, trimmed, with any run of whitespace collapsed to a single space. */
79	    private static String canonicalName(String value) {
80	        if (value == null) {
81	            return "";
82	        }
83	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
84	    }
85	}
