1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request telephone
11	 * is E.164 and the email lower-cased) and before {@link BuildOwner}. Rejects the request with
12	 * {@link DuplicateIdentityException} (handled as 409) when it collides with an existing owner.
13	 *
14	 * <p>The household is keyed on (lastName, postcode): the new owner's deterministic
15	 * {@link OwnerIdentity#householdId householdId} is computed from those fields, and an existing owner
16	 * with the same household id is a <em>household duplicate</em>. A second owner in an existing household
17	 * is therefore rejected — <em>unless</em> the request opts in with {@code sharesHousehold: true}, which
18	 * bypasses this whole duplicate block so the owner is created as a declared household member.
19	 *
20	 * <p>Independently of the household, an existing owner with the same normalized telephone and email is a
21	 * <em>contact duplicate</em> and is also rejected (unless the request opted in above).
22	 */
23	public class EnsureUniqueOwnerIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        // A declared household member opts in with sharesHousehold=true and bypasses the whole
28	        // duplicate block, so it is created even though it shares an existing owner's household.
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
33	        String contactKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), null);
34	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
35	        for (Owner existing : ownerRepository.findAll()) {
36	            // A soft-deleted owner is no longer a live identity: skip it, so a duplicate that would
37	            // otherwise block is allowed when its only match has been deleted.
38	            if (Boolean.TRUE.equals(existing.getDeleted())) {
39	                continue;
40	            }
41	            // Household duplicate: same deterministic householdId (same lastName + postcode).
42	            String existingHousehold =
43	                    OwnerIdentity.householdId(existing.getLastName(), existing.getPostcode());
44	            if (householdId.equals(existingHousehold)) {
45	                throw new DuplicateIdentityException(identityKey);
46	            }
47	            // Contact duplicate: same normalized telephone and email, regardless of household.
48	            String existingContact = OwnerIdentity.key(OwnerIdentity.toE164(existing.getTelephone()),
49	                    OwnerIdentity.normalizeEmail(existing.getEmail()), null);
50	            if (contactKey.equals(existingContact)) {
51	                throw new DuplicateIdentityException(identityKey);
52	            }
53	        }
54	    }
55	}
